#!/bin/bash

#####################################
## removing linkage disequilibirum ##
#####################################

  plink \ 
    --file populations.plink  \ #plink file format generated by populations (Stakcs) with the --plink parameter
    --allow-extra-chr \ #plink is made for human genomes, to use our data it was necessary specifying to ignore the names of the Culex pipiens chromosomes
    --indep-pairwise 50 10 0.2 \
    --out dataset_pruned


#######################################
## removing missing data/individuals ##
#######################################

  plink \
    --file dataset_pruned \
    --allow-extra-chr \
    --extract dataset_pruned.prune.in \ #output file of --indep-pairwise containing the unlinked SNPs
    --mind 0.2 \ #to remove individuals with > 20% missing genotypes
    --geno 0.05 \ #to remove loci with > 5% missing genotypes
    --make-bed \
    --out dataset_pruned_clean



##################################
## removing related individuals ##
##################################

  plink \
    --bfile dataset_pruned_clean \ 
    --allow-extra-chr \ 
    --rel-cutoff 0.4 \ #to exclude clones and siblings from the dataset
    --out kinship_filtered

  plink \
    --bfile dataset_pruned_clean \
    --allow-extra-chr \
    --keep kinship_filtered.rel.id \ #output file from --rel-cutoff parameter containing the list of the unrelated individuals
    --out Dataset_B
    


